import java.util.Scanner;

class Cat {
    String name;
    int fish;

    void report() {
        System.out.println(name + " 有 " + fish + " 条小鱼干喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Cat c = new Cat();
        c.name = "{name}";
        c.fish = sc.nextInt();
        c.report();
    }
}
